"""Loading the reference data generated by python/tools/matlab/gen_refdata.m."""

import json
import pathlib

import numpy as np
import torch
from scipy.io import loadmat

from saivdr.dcnn.matlab_compat import from_matlab_array

REFDATA = pathlib.Path(__file__).parent / "refdata"

# MATLAB name-value arguments -> Python keyword arguments
_KWARGS = {
    "DecimationFactor": "decimation_factor",
    "NumberOfComponents": "number_of_components",
    "NumberOfChannels": "number_of_channels",
    "NoDcLeakage": "no_dc_leakage",
    "Mode": "mode",
    "Direction": "direction",
    "TargetChannels": "target_channels",
    "OriginalDimension": "original_dimension",
    "NumberOfLevels": "number_of_levels",
    "PolyPhaseOrder": "polyphase_order",
    "NumberOfVanishingMoments": "number_of_vanishing_moments",
}

_KINDS = {"serial2d": "serial", "serial3d": "serial"}


def tolerance(dtype, gradient=False):
    """(rtol, atol) for comparing with MATLAB in double or single precision."""
    if dtype == "double":
        return (1e-9, 1e-10) if not gradient else (1e-8, 1e-9)
    return (1e-4, 1e-5) if not gradient else (1e-4, 1e-4)


def torch_dtype(dtype):
    return torch.float64 if dtype == "double" else torch.float32


def case_files(group):
    """Return the sorted list of MAT-files of a group (fails if there are none)."""
    files = sorted((REFDATA / group).glob("*.mat"))
    if not files:
        raise FileNotFoundError(f"No reference data in {REFDATA / group}; run gen_refdata.m")
    return files


def text(m, key):
    v = m[key]
    return str(v[0]) if v.size else ""


def kwargs(params_json):
    params = json.loads(params_json) if params_json else {}
    if isinstance(params, list):  # jsonencode of an empty struct
        params = {}
    return {_KWARGS[k]: v for k, v in params.items()}


def load(path):
    return loadmat(path)


def array(m, key, kind, dtype=torch.float64):
    size = m.get(key + "_size")
    return from_matlab_array(m[key], _KINDS.get(kind, kind), size=size, dtype=dtype)


def cell(m, key):
    return [np.asarray(v) for v in m[key].ravel()]


def names(m, key="names"):
    return [str(np.asarray(v).ravel()[0]) for v in m[key].ravel()]


def params_dict(m):
    """``{name: {'Angles', 'Mus'[, 'NoDcLeakage']}}`` stored in a MAT-file."""
    out = {}
    angles = cell(m, "angles")
    mus = cell(m, "mus")
    ndl = np.asarray(m["nodcleakage"]).ravel()
    for i, name in enumerate(names(m)):
        p = {"Angles": angles[i].reshape(-1), "Mus": mus[i].reshape(-1)}
        if not np.isnan(ndl[i]):
            p["NoDcLeakage"] = bool(ndl[i])
        out[name] = p
    return out
